from pathlib import Path
import json
root=Path('out/engine3d/phase23')
def read(file):return json.loads((root/'analysis'/file).read_text(encoding='utf-8'))
final=read('final-status.json');assert final['phase23Complete']
checks=read('checks.json');assert len(checks)==17 and all(c['exitCode']==0 for c in checks)
runs=read('live-runs.json');assert len(runs)==2 and all(r['exitCode']==0 for r in runs)
metrics=read('metrics.json');cold,pop=metrics;gates=read('real-world-gates.json');anti=read('anti-hardcode.json');integrity=read('integrity.json');transitions=read('canonical-transitions.json')
def table(headers,rows):
 def cell(v):return str(v).replace('|','\\|').replace('\n',' ')
 return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+'\n'.join('| '+' | '.join(cell(x) for x in row)+' |' for row in rows)
def link(file):return '['+file+'](out/engine3d/phase23/'+file+')'
sections=[]
def section(title,body):sections.append('## '+title+'\n\n'+body.strip()+'\n')
section('Objective',f'''**PHASE23 COMPLETE: YES — implementation gate PASS.** Research v4 implementada e validada com aquisição orientada a requisitos factuais, dois benchmarks live, replay offline e auditoria. Readiness real é um resultado separado: Cold **{cold['quality']['resultState']}**, **{cold['eligible']}/5**, **{cold['ranking']}**; população **{pop['quality']['resultState']}**. Factual safety prevaleceu sobre score.''')
section('Starting State','''`main`, HEAD esperado e preservado `d1b8d003432a376002cea45391b42420ab345334`, inicialmente CLEAN, igual a origin/main. Lidos integralmente CLONAI_HANDOFF, PHASE21_REPORT, PHASE22_REPORT e handoff incompleto como histórico; revisados código, testes, helpers e artefatos locais. Os relatórios e artefatos Phase22 não foram reescritos. Sem reset, commit/push ou Phase24.''')
section('Phase22 Baseline','''Baseline fresca: typecheck e 764 testes únicos PASS antes da implementação. Registry 50/8/5. Revisadas as falhas de cada candidato em `analysis/phase22-candidate-failures.json`: origem insuficiente, presença ausente/histórica/incompatível, contexto temporal e ruído de tipo. O candidato mais próximo da elegibilidade tinha medição admitida e presença com uma origem.

Nota aritmética: o relatório histórico registra 278 testes research. A execução atual das quatro suítes legadas confirmou **280 = 50 + 115 + 39 + 76**, sem modificar testes históricos. O número histórico foi preservado no documento original; não se apresenta 278 como uma soma correta.''')
section('Research v4 Architecture','''Opt-in `researchVersion: 4`, `web.v4`. Request → bootstrap de candidatos → FactGap → EvidenceRequirementPlan → QueryFamily/SourceStrategy/ProviderCapability → aquisição segura → snapshots → núcleo EvidencePack/SourceGraph → reavaliação do mesmo fato → stop/exhaustion. Reutilizados core, writer, ranking e transporte existentes. Novos módulos `src/research/v4/{contracts,semantics,planning,session}.ts`, `web/{v4,v4-providers,output-v4}.ts`, testes e auditoria. V1/v2/v3 não recebem o novo comportamento.''')
section('Fact Gaps',f'''Cold: {cold['factGapsCreated']} criados, {cold['factGapsClosed']} CLOSED, {cold['factGapsExhausted']} EXHAUSTED. O modelo guarda factKey, entidade, métrica/qualifier, evidências, raízes/ecossistemas existentes, locators/citações excluídos, requisito ausente, classes/estratégias preferidas, gain estimate, prioridade, histórico, budget e status. Lacunas de formato/idioma/fetch são diagnósticos distintos; EXHAUSTED não significa falso. '''+link('review/gap-analysis.md')+'.')
section('Evidence Requirements','''Cada gap explicita o que poderia fechá-lo: tipo de evidência, identidade, semântica, requisito temporal, origem nova e regra de admissão. Exemplos genéricos: presença atual de residentes usuais/civis permanentes; mínimo de ar registrado com data/janela de observação. Snippets, abstracts, memória interna, staff, números de população isolados e data de publicação como data do evento são substitutos proibidos. Autoridade e quorum originais não foram relaxados.''')
section('Source Ecosystems','''Taxonomia genérica de estatística nacional, governo local/regional, município, meteorologia, academia/repositório, catálogo de dados, registro geográfico, arquivo, referência, notícias e OTHER. Classificação usa sinais do snapshot/publisher. Categoria de descoberta não é autoridade nem independência. Distribuições reais estão em metrics.json e '''+link('review/source-ecosystems.md')+'.')
section('Strategy Planner','''Estratégias ordenadas registram ecossistema, provider, família, propósito, por que podem ampliar independência, origens excluídas, evidência esperada, custo/valor e budget. Ecossistema diferente recebe preferência; mesmo publisher/domínio fica diagnosticado/depriorizado e nunca conta automaticamente como segunda origem. A resolução final continua no SourceGraph e nas raízes do fato.''')
section('Query Families','''Famílias distintas para dataset, censo, registro de localidade, registro histórico, observação, origem citada e citação reversa. Derivadas de entidade, métrica, qualifier, gap e ecossistema; nenhuma entidade/temperatura do benchmark foi incluída como seed. Falha registrada esgota a família conforme budget, permitindo rotação. Não há benefício por reformulações cosméticas da mesma query.''')
section('Provider Capabilities','''Cada provider declara ecossistemas, query types, metadados, limite/custo, disponibilidade e expectativa de independência. DataCite Public API e CKAN textual foram integrados e testados por fixtures generalizáveis de datasets. Referências da auditoria: [DataCite API](https://support.datacite.org/docs/api), [DataCite queries](https://support.datacite.org/docs/api-queries), [CKAN](https://docs.ckan.org/en/2.11/api/index.html), [catálogo público UK](https://guidance.data.gov.uk/get_data/api_documentation/).

OpenAlex foi desativado na v4: a [política atual](https://blog.openalex.org/openalex-api-new-features-and-usage-based-pricing/) exige chave e uso tarifado, e esta fase não usa chaves, quotas de demonstração como dependência ou fallback pago. O caminho histórico v3 foi preservado. MediaWiki, Wikidata e Crossref continuam disponíveis dentro de suas capacidades declaradas.''')
section('Independent Acquisition',f'''Cold realizou {cold['strategiesAttempted']} estratégias, {cold['queryFamiliesAttempted']} famílias e {cold['attempts']} tentativas ligadas a gaps. Houve {cold['newIndependentOrigins']} incrementos positivos de raízes para fatos-alvo e {cold['sameOriginDiscoveriesRejected']} descobertas de origem já conhecida diagnosticadas. Uma fonte adquirida sem evidência do fato não fecha gap. '''+link('review/independent-acquisition.md')+'.')
section('Citation Pursuit','''Citações anexadas a EVs geram pursuit explícito do original. Relações DataCite de derivação/versão/citação são registradas; paper e dataset citado não viram automaticamente duas origens. Identidade explícita de publisher em domínios diferentes e lineage declarado podem reduzir independência. Reverse-citation usa metadados públicos e permanece diagnóstico UNPROVEN; sem valor factual proveniente de metadados.''')
section('Dataset Discovery',f'''Cold descobriu {cold['datasetsDiscovered']} identidades de datasets e produziu {cold['datasetEvidence']} EVs de dataset; população: {pop['datasetsDiscovered']} / {pop['datasetEvidence']}. Identidade preserva publisher, versão/data, formato/schema informado, URL e lineage. CSV/TSV usam o parser limitado existente e offsets de linha/célula. Na v4, nome igual ou parecido sozinho permanece CANDIDATE: ID ou contexto administrativo precisa de prova com span validado em snapshot já adquirido. Contexto ausente/forjado/incompatível recusa a linha. Isso é conservador e limita o yield real; não há lookup universal de identificadores.''')
section('Temporal Evidence','''TemporalEvidenceRequirement distingue CURRENT, HISTORICAL, OBSERVATION_PERIOD, EVENT_DATE, CENSUS_DATE e PUBLICATION_DATE. O planejador seleciona o requisito pertinente. `evaluationDate` é input explícito; replay não consulta relógio. Passado ou presença antiga não prova residência atual. Publicação não preenche janela/data de medição ausente.''')
section('Residency Semantics','''ResidencyEvidenceAssessment registra presence type, currentness, semântica de população, autoridade, origem, match e motivos. Residentes usuais e civis explicitamente permanentes têm suporte literal próprio. Staff de pesquisa/militar, turistas, trabalhadores temporários, presença sazonal, habitantes históricos e assentamento abandonado ficam separados. Quantidade censitária sozinha nunca se transforma em população permanente. Vocabulário limitado EN/PT; sem tradução interna como Evidence. '''+link('review/residency-evidence.md')+'.')
section('Measurement Semantics','''Preservados os guards de mínimo registrado versus médias, menor máxima, wind chill e superfície/satélite. Modelled minima, feels-like e heat index não viram mínimo do ar. MeasurementContextAssessment separa qualifier, scope e datas/janela/publicação. Não foi criado parser térmico universal. '''+link('review/measurement-context.md')+'.')
section('Station/Settlement','''Identidades distintas, inclusive nomes iguais. Transferência exige policy SOURCED_OBSERVATION_SITE e relação explícita source-backed; não usa proximidade/similaridade como identidade. A revisão registra estação, settlement, aresta, fonte e contexto literal. Distância só é apresentada se estiver no snapshot. Presença permanente continua requisito separado.''')
section('Conflict Resolution','''ConflictResolutionTask investiga definição, qualifier, janela, estação/localidade, revisão, método e lineage. Não escolhe maior autoridade para resolver contradição. Janelas explicitamente diferentes permanecem fatos separados; quando o mesmo valor tem múltiplas janelas, os novos IDs são identificados como novos, sem simular promoção do antigo. Contexto ausente não resolve conflito. '''+link('review/conflict-resolution.md')+'.')
section('Eligibility Gain','''Estimativa determinística favorece um requisito de distância da elegibilidade e fatos 1/2 antes de 0/2, incorporando custo, fetchability, autoridade provável, diversidade e falhas. É heurística, sem ML. Na prática, providers disponíveis e identificadores faltantes continuam limitando a aquisição útil.''')
section('Failure Memory','''A primeira execução real de população expôs repetição da mesma URL bloqueada entre facts; foi preservada em development-attempts. Uma regressão e memória global provider+query foram adicionadas antes das coletas finais.

AcquisitionIntent guarda inputs observados: gap/strategy/family/provider, query/result URLs, fetch IDs, source subsets antes/depois, diagnóstico e timestamp de aquisição. AcquisitionAttempt deriva acceptedSources, EVs novos, raízes novas, fechamento e falha. O replay rederiva os estados correspondentes dos snapshots; não reutiliza contadores como conclusão.''')
section('Exhaustion','''OPEN/PARTIAL/CLOSED/EXHAUSTED/BUDGET_EXHAUSTED/CONFLICTED e BLOCKED_FORMAT/LANGUAGE/FETCH são estados separados. Limites por gap, estratégia, família, domínio, queries, fetches, bytes, timeout e rodadas permanecem ativos. Sem estratégias executáveis termina capabilities-exhausted; isso não afirma falsidade do fato.''')
section('Stop Early','''Um gap fechado não continua recebendo estratégia; readiness interrompe o loop. O teste integrado comprova duas origens e ranking válido em uma única tentativa de aquisição, com fixtures fictícias. O live mantém as falhas e para por readiness/capability/budget, sem coletar fontes apenas para elevar contagem.''')
section('Candidate Quality',f'''Pool distingue source-backed, search-only, observation sites e fitness. Tipos de locality vêm de texto explícito/EntityGraph; não são inferidos de um número. Países, seções, labels métricos e pronomes deíticos são rejeitados genericamente, sem lista de nomes Cold. UNCONFIRMED pode permanecer como candidato de descoberta, mas não entra como settlement comprovado no ranking. Cold terminou com {cold['candidates']} candidatos relevantes; distribuição de fitness {cold['entityFitness']}. '''+link('review/candidate-quality.md')+'.')
section('Cold Benchmark',f'''Executado live após {final['v4Tests']['pass']}/{final['v4Tests']['tests']} testes v4 PASS e preflight histórico. Tema integral e mesma policy da Phase22: TEMPERATURE, MINIMUM_RECORDED, PERMANENT_POPULATION, quorum 2 e exceções de autoridade HIGH preservadas. Sem fontes preparadas ou snapshots antigos como inputs da execução real.

{cold['queries']} queries; {cold['results']} resultados; {cold['fetches']} fetches; {cold['acceptedSources']} fontes aceitas; {cold['supported']} SUPPORTED; {cold['corroborated']} CORROBORATED. Estado **{cold['quality']['resultState']}**, writer **{cold['writer']}**. Scope SESSION_CANDIDATES e guard global preservados.

'''+table(['Gate','Resultado','Evidência'],[[k,'PASS' if v['passed'] else 'FAIL',v['detail']] for k,v in gates.items()]))
section('Canonical Fact Transitions',f'''**{cold['strictPhase22FactsOneToTwo']} fatos Cold da Phase22 com o mesmo ID passaram de uma para pelo menos duas raízes.** Cada linha guarda ID, tuple, status/origens antes/depois e motivo. Ausência no novo corpus e novos IDs não contam como transição. Bootstrap→final é outra métrica e não substitui esta comparação. '''+link('analysis/canonical-transitions.json')+'.')
section('Cold Eligibility',f'''**{cold['eligible']}/5**, **{cold['ranking']}**. Cada checklist e exclusão permanece em '''+link('review/cold-eligibility.md')+'''. Nenhum mínimo foi trocado por média, nenhum research staff virou população permanente e nenhum item ausente foi inventado. Mesmo cinco itens de sessão não autorizariam “top 5 do mundo”.''')
section('Population Benchmark',f'''Reutilizado o benchmark real de população recenseada da Phase22. {pop['queries']} queries, {pop['results']} resultados, {pop['fetches']} fetches, {pop['acceptedSources']} fontes; {pop['facts']} fatos candidatos, {pop['factsAdmitted']} admitidos, {pop['corroborated']} CORROBORATED; **{pop['quality']['resultState']}**. Isso exercita generalização, não demonstra automaticamente readiness. Writer v2/QUANTITY realization não foi implementado para contornar pesquisa incompleta.''')
section('Corroboration Yield',table(['Métrica','Cold','Population'],[[k,cold['yield'][k],pop['yield'][k]] for k in cold['yield']])+'''

New independent origins conta incrementos positivos dos fatos-alvo após resolução de origem. Uma nova origem que só contém informação alheia não melhora esse yield. Denominadores queries/fetches são da aquisição orientada a gaps; bootstrap é explicitado nos totais gerais. Divisão por zero é null, não infinito. Near-copy rejeitada conta source IDs adquiridos distintos envolvidos em relação, não pares repetidos por fato. '''+link('review/corroboration-yield.md')+'.')
section('Phase22/23 Comparison','''Comparação de observações live distintas, não A/B de corpus fixo. O número de fontes não é critério de vitória. Phase22/23, métricas completas e caveats: '''+link('analysis/phase22-23-comparison.json')+'.\n\n'+table(['Benchmark','Queries','Fontes','Publishers','Grupos','Candidatos','Admitidos','Elegíveis'],[[x['label'],x['queries'],x['acceptedSources'],x['publishers'],x['originGroups'],x['candidates'],x['factsAdmitted'],x['eligible']] for x in metrics]))
section('Source Gaps',table(['Benchmark','Tipo','Quantidade'],[[x['label'],k,n] for x in metrics for k,n in x['gapKinds'].items() if k.startswith('SOURCE_')])+'''

Falhas de provider, HTTP, robots, formato, idioma, dataset identity e budget permanecem nos logs/attempts. Não houve retry sem limite, bypass ou fallback pago. PDF e idioma bloqueados de alta prioridade são recomendações futuras, não EVs gerados pelo modelo.''')
section('Extraction Gaps','''A melhoria central foi aquisição orientada a fatos, com alterações de extração limitadas às semânticas solicitadas. Permanecem gramáticas fechadas, records/tabelas não suportados, ausência de identificadores/contexto administrativo, idiomas além de EN/PT, páginas JS e PDFs. Uma linha nome-only pode ser guardada como fonte/diagnóstico, mas não admitida como nova evidência identificada. Casos originais permanecem em source/structured diagnostics, datasets e reviews.''')
section('Replay','''**PASS / ZERO NETWORK.** Duas sessões v4 reconstruídas desde bootstrap e cada subset de fontes das tentativas, com comparação de model/attempts/pool/tasks/citations/datasets/yield, SourceGraph, EVs, fatos, eligibility, ranking, writer e processing fingerprints. HTTP/HTTPS request/get, fetch, DNS e transport foram substituídos por falha contadora. Nove packs e seis sessões históricas também passaram no preflight. Roteiro/plano são N/A quando o writer permanece bloqueado; não se alega reprodução de MP4 inexistente. '''+link('analysis/replay.json')+'.')
section('Security','''**PASS.** SecureHttpClient continua a fronteira dos providers e fontes: SSRF, todas as respostas DNS públicas, socket pinning, redirects, robots, MIME/charset e limites de streaming/bytes/tempo. Sem scraping Google/Bing, CAPTCHA/JS/paywall bypass, PDF parser/OCR ou execução de fórmulas. Reviews escapam conteúdo externo. Identidade declarada do publisher é heurística, não autenticação universal. '''+link('analysis/security.json')+'.')
section('Anti-hardcode',f'''**PASS**, {anti['scannedFiles']} arquivos examinados, zero BLOCKER. Alvos derivados das sessões Phase22/23 incluem entidades, valores, publishers, domínios/URLs finais e citados, estações e ranking. Providers genéricos, documentação e coincidências em fixtures fictícios/arquivos anteriores são classificados explicitamente. Outputs adquiridos ficam fora dos seeds e do Git. '''+link('analysis/anti-hardcode.json')+'.')
section('Determinism','''Mesmo request/snapshot/trace produz os mesmos fingerprints. Ordenação de fontes invertida, tampering externo re-assinado, cadeia de source subsets e conteúdo do model são testados. Timestamp é metadado adquirido; o replay não consulta relógio. A web live muda; determinismo aqui significa reconstrução de observações registradas, não resultados iguais entre coletas independentes.''')
section('Performance',table(['Benchmark','Live ms','Bytes','Queries','Fetches'],[[x['label'],x['elapsedMs'],x['bytes'],x['queries'],x['fetches']] for x in metrics])+'''

Replays reconstroem subsets e têm custo de CPU/memória maior que apenas ler o pack final. Cache por conjunto de source IDs evita rebuilds repetidos dentro de uma sessão. Tempos isolados do replay estão em replay.json e tempos por comando em checks.json; não se somam esses valores ao tempo live.''')
section('Tests',f'''**{final['v4Tests']['pass']}/{final['v4Tests']['tests']} v4 PASS. {final['uniqueFastTests']} testes únicos na suíte completa. 17/17 comandos obrigatórios PASS.** Fixtures fictícios, providers/DNS/transport mockados, sem internet nos testes. Testes históricos não foram alterados. A suíte cobre todos os grupos solicitados: gap/requirements/ecosystems/strategies/families/capabilities, citation/reverse/dataset identity, temporal/residency/measurement/stations, conflicts, priority/failure/budgets/exhaustion/stop, yield/candidate noise/superlative, replay/tamper, snippets e ausência de conhecimento interno.

'''+table(['Comando','Exit','Testes','s'],[[c['command'],c['exitCode'],c['counts'].get('tests','—'),c['elapsedSeconds']] for c in checks]))
section('Registry','''Engine3D **50** / SFX **8** / VISUAL **5**. Sem assets, dependências/versões, Writer, Engine3D ou MP4 novos. Os 12 vídeos históricos mantêm SHA-256. Catálogo validado. '''+link('analysis/integrity.json')+'.')
section('Compatibility','''V1/v2/v3 continuam opt-out e com rederivação/replay históricos idênticos. Novos campos e comportamento são v4; guards de transporte não foram enfraquecidos. Canonical IDs existentes são preservados quando a semântica continua igual; splits por janela explicitamente distinta são novos fatos e nunca contados como promoção. package-lock, testes antigos, relatórios Phase21/22 e render estão intactos.''')
section('Limitations','''Sem busca web genérica keyless, cobertura exaustiva, autenticação universal de publisher, parser universal de datasets/identificadores, PDF/OCR, JS ou tradução geral. Os providers novos demonstram descoberta/lineage por fixtures e resultados live, mas metadados não garantem full text ou evidência útil. Os pesos de custo/fetchability são heurísticos fixos, sem calibração estatística. Snapshot lineage só cobre relações observáveis. Scope por sessão, corpus e budget limitam conclusões. Dados volumosos continuam locais/ignorados, não são transportados por um commit do código.''')
ratings=[('GAP MODELING','GOOD'),('STRATEGY PLANNING','GOOD'),('QUERY DIVERSITY','GOOD'),('SOURCE ECOSYSTEM DIVERSITY','ACCEPTABLE' if gates['R2']['passed'] else 'WEAK'),('INDEPENDENT ACQUISITION','GOOD' if gates['R4']['passed'] else 'WEAK'),('ORIGIN RESOLUTION','GOOD'),('DATASET DISCOVERY','ACCEPTABLE'),('TEMPORAL REASONING','ACCEPTABLE'),('RESIDENCY SEMANTICS','GOOD'),('MEASUREMENT SEMANTICS','GOOD'),('CONFLICT RESOLUTION','ACCEPTABLE'),('BUDGET EFFICIENCY','ACCEPTABLE' if cold['newIndependentOrigins'] else 'WEAK'),('CANDIDATE QUALITY','GOOD'),('CORROBORATION','GOOD' if gates['R5']['passed'] else 'WEAK'),('RANKING SAFETY','STRONG'),('REPLAYABILITY','STRONG'),('SECURITY','STRONG'),('GENERALIZATION','ACCEPTABLE'),('OVERALL AUTONOMY','ACCEPTABLE')]
section('Honest Assessment',table(['Dimensão','Avaliação'],ratings)+f'''\n\nO target principal (um gap real 1→2 e um fato real CORROBORATED) {'foi demonstrado' if gates['R4']['passed'] and gates['R5']['passed'] else 'não foi demonstrado pelos critérios estritos'}. Implementation PASS não implica real-world PASS. Os gates reais acima permanecem explícitos. Não houve roteiro/MP4 para preencher lacunas, nem ajuste do quorum para elevar resultado.''')
section('Autonomy Level','**'+final['autonomy']+'**. '+('Proposta baseada nos ganhos reais indicados nos gates; não LEVEL5.' if 'PROPOSED' in final['autonomy'] else 'LEVEL4C mantido: não houve ganho estrito suficiente para promoção. Não LEVEL5.'))
section('Next Recommendation','''Uma recomendação: melhorar aquisição de evidência identificável de presença atual em registros oficiais/localidades, com ganho de origem por fato demonstrado antes de ampliar formatos ou writer. **Phase24 não iniciada; sem commit/push automático. PARAR.**

Artefatos finais: '''+link('analysis/final-status.json')+', '+link('analysis/metrics.json')+', '+link('analysis/canonical-transitions.json')+', '+link('analysis/real-world-gates.json')+', '+link('analysis/checks.json')+'. Nove reviews consolidadas em `out/engine3d/phase23/review/`; snapshots e todos os outputs ficam locais.')
assert len(sections)==43,len(sections)
Path('PHASE23_REPORT.md').write_text('# Phase 23 — Research v4 — Final report\n\nData: 2026-10-28. Checkpoint Phase22 preservado.\n\n'+'\n'.join(sections),encoding='utf-8')
print(json.dumps({'report':'PHASE23_REPORT.md','sections':len(sections),'complete':True,'gates':gates}))
